import {enrichSpecies,EMPTY_MOVE} from './move-learning.mjs';
import {moveData,damageEstimate,speed,effectiveness} from './combat-rules.mjs';
const usable=(mon)=>mon.moves.map((m,i)=>({...moveData(m),slot:i})).filter(m=>m.left>0&&!m.disabled&&!(mon.volatile?.taunt&&m.status));
export function scoreMove(mon,target,raw,chart,field={},context={}){const m=moveData(raw),ratio=mon.hp/mon.max,damage=damageEstimate(mon,target,m,chart,field),threat=Math.max(0,...(context.observed||[]).map(x=>damageEstimate(target,mon,x,chart,field))),faster=(m.priority||0)>0||speed(mon,field)>=speed(target,field);let score=damage/Math.max(1,target.max)*100*(m.accuracy/100);
 if(damage>=target.hp)score+=faster?120:60;if(threat>=mon.hp&&!faster)score*=.5;
 if(m.status){score=0;if(m.boosts?.some(b=>b.change>0)&&ratio>.55&&threat<mon.hp*.45)score=27+m.boosts.reduce((n,b)=>n+Math.max(0,b.change)*(6-(mon.stages?.[b.stat]||0))*1.5,0);if(m.boosts?.length&&m.boosts.every(b=>b.change>0&&(mon.stages?.[b.stat]||0)>=6))score=0;if(m.boosts?.some(b=>b.change<0)&&!m.boosts.every(b=>(target.stages?.[b.stat]||0)<=-4))score=20;
 if(m.ailment&&m.ailment!=='none'&&!target.status&&!target.types.includes(m.type==='poison'?'poison':'__'))score=({sleep:46,paralysis:40,burn:target.atk>=target.spa?44:24,poison:32,confusion:26,freeze:40})[m.ailment]||0;
 if(['recover','roost','soft-boiled','slack-off','milk-drink','rest','synthesis','moonlight','morning-sun','wish'].includes(m.slug)||m.healing>0)score=ratio<.6&&(threat<mon.hp||faster)?(1-ratio)*95+(m.slug==='rest'&&mon.status?15:0):0;
 if(['protect','detect','endure'].includes(m.slug))score=(target.status==='toxic'||mon.volatile?.seeded||target.volatile?.recharge)?45:mon.volatile?.lastProtect?0:8;
 if(m.slug==='leech-seed')score=target.volatile?.seeded||target.types.includes('grass')?0:36;
 if(['stealth-rock','spikes','toxic-spikes','sticky-web'].includes(m.slug)){const hazard=context.enemySide?.hazards?.[m.slug]||0;score=hazard>=(m.slug==='spikes'?3:m.slug==='toxic-spikes'?2:1)?0:((context.enemyReserves||0)>1?38:8)}
 if(['reflect','light-screen','aurora-veil'].includes(m.slug))score=mon.volatile?.[m.slug==='reflect'?'reflect':'lightScreen']?0:30;
 if(m.slug==='taunt')score=target.volatile?.taunt?0:target.moves.filter(x=>moveData(x).status).length*12;
 if(['rain-dance','sunny-day','sandstorm','hail','snowscape'].includes(m.slug)){const weather=({'rain-dance':'rain','sunny-day':'sun',sandstorm:'sand',hail:'snow',snowscape:'snow'})[m.slug];score=field.weather===weather?0:mon.types.includes(weather==='rain'?'water':weather==='sun'?'fire':weather==='snow'?'ice':'rock')?32:6}
 if(m.slug==='substitute')score=ratio>.7&&!mon.volatile?.substitute?24:0;
 }else{if(m.ailmentChance&&!target.status)score+=m.ailmentChance*.12;if(m.drain>0)score+=Math.min(1-ratio,damage/mon.max)*m.drain*.3;if(m.drain<0&&damage*(-m.drain/100)>=mon.hp)score-=40;if(m.flinchChance&&faster)score+=m.flinchChance*.2;if(m.maxHits>1)score*=((m.minHits+m.maxHits)/2);if(!effectiveness(mon,target,m,chart))score=-100}
 if(mon.volatile?.taunt&&m.status)return-Infinity;return score;
}
export function chooseAction(team,enemy,chart,field={},context={}){const mon=team.mons[team.active],target=enemy.mons[enemy.active],moves=usable(mon),candidates=moves.map(m=>({move:m.slot,score:scoreMove(mon,target,m,chart,field,{...context,enemySide:field.sides?.[enemy.pid],enemyReserves:enemy.mons.filter(p=>p.hp>0).length-1})})).sort((a,b)=>b.score-a.score||a.move-b.move);let best=candidates[0]||{move:0,score:-100};
 if(!mon.volatile?.trapped&&(team.switchTurn??-99)<(context.turn||1)-2){const visible=context.observed||[],danger=Math.max(0,...visible.map(m=>damageEstimate(target,mon,m,chart,field)));for(let slot=0;slot<team.mons.length;slot++){const reserve=team.mons[slot];if(slot===team.active||reserve.hp<=0)continue;const attack=Math.max(0,...usable(reserve).map(m=>scoreMove(reserve,target,m,chart,field,context))),risk=Math.max(0,...visible.map(m=>damageEstimate(target,reserve,m,chart,field))),entry=field.sides?.[team.pid]?.hazards?.['stealth-rock']?reserve.max*.125:0;const score=attack-risk/reserve.max*35-14-entry/reserve.max*100;if((best.score<12||danger>=mon.hp||visible.length&&danger>mon.max*.5&&risk<reserve.max*.2)&&score>best.score+8&&reserve.hp>risk+entry)best={swap:slot,score}}}
 const {score,...action}=best;return action;
}
export function bestReplacement(team,enemy,chart,field={}){return team.mons.map((p,slot)=>({slot,score:p.hp>0?Math.max(0,...usable(p).map(m=>damageEstimate(p,enemy.mons[enemy.active],m,chart,field)))*p.hp/p.max:-1})).sort((a,b)=>b.score-a.score||a.slot-b.slot)[0]?.slot??0}

export function prepareAiMoves(mon,dex){const available=(enrichSpecies(dex[mon.id])?.learnset||[]).filter(m=>m.level<=mon.level),offense=available.filter(m=>!m.status&&m.power>0).sort((a,b)=>b.power*(mon.types.includes(b.type)?1.3:1)*(b.special?mon.spa:mon.atk)-a.power*(mon.types.includes(a.type)?1.3:1)*(a.special?mon.spa:mon.atk)),selected=[],types=new Set();for(const m of offense)if(!types.has(m.type)&&selected.length<3){selected.push(m);types.add(m.type)}for(const m of offense)if(selected.length<3&&!selected.some(x=>x.id===m.id))selected.push(m);const supports=available.filter(m=>m.status).sort((a,b)=>{const score=m=>/recover|roost|synthesis|soft-boiled/.test(m.slug)?10:/swords-dance|dragon-dance|calm-mind|nasty-plot/.test(m.slug)?8:/will-o-wisp|thunder-wave|toxic|sleep-powder|spore/.test(m.slug)?7:/protect|leech-seed|reflect|light-screen/.test(m.slug)?6:3;return score(b)-score(a)});if(supports[0])selected.push(supports[0]);for(const old of mon.moves)if(selected.length<4&&!selected.some(m=>m.id===old.id))selected.push(old);while(selected.length<4)selected.push(EMPTY_MOVE);mon.moves=selected.slice(0,4).map(m=>({...m,left:m.pp}));return mon}
